def chk3(items, w=128):
    return table(["", "😀", "🙂", "😕"], [[x, '<span class="chk"></span>', '<span class="chk"></span>', '<span class="chk"></span>'] for x in items], [f"{w}mm", "18mm", "18mm", "18mm"])


def extrait(n, titre, html, fs=10.1):
    """Extrait du roman, mise en page « livre »."""
    return (f'<div class="card" style="{SERIF};background:#FFFCF5;border:1.5px solid #d8c9a8;font-size:{fs}pt;padding:3mm 4.5mm">'
            f'<div class="flex" style="justify-content:space-between;margin-bottom:1mm;font-family:Poppins"><span>{F} <b style="color:{MC}">Chapitre {n} · {titre}</b></span><span class="xs muted">{LIVRE}, Hélène Marchal</span></div>{html}</div>')


def P_(t):
    return "".join(f'<p style="margin:0 0 1.2mm 0;text-indent:5mm">{x}</p>' for x in t.strip().split("\n"))


CH1 = P_("""Depuis trois mois, nous habitons au troisième étage d'une vieille maison d'Outremeuse, un quartier de Liège. Maman dit que c'est provisoire. Ilyas, mon petit frère, dit que c'est un château. Moi, je dis que c'est une maison qui parle : quand on monte l'escalier, chaque marche grince d'une voix différente.
La septième marche, surtout. Elle ne grince pas, elle gémit. Ce soir-là, je rentrais de l'école et j'étais de mauvaise humeur. En classe, je n'avais presque rien compris au cours d'histoire et personne ne m'avait parlé à la récréation. J'ai donné un coup de pied dans la septième marche. Le bois a craqué, et la planche s'est soulevée.
— Zara ! Qu'est-ce que tu as cassé ? a crié Maman depuis la cuisine.
— Rien ! ai-je répondu. C'est l'escalier qui est vieux.
Je me suis penchée. Sous la planche, dans la poussière, il y avait une petite boîte en fer, toute rouillée. Sur le couvercle, on devinait encore le dessin d'une dame qui buvait du chocolat. J'ai soulevé le couvercle, le cœur battant.
Dans la boîte, il n'y avait pas de trésor. Seulement une enveloppe jaunie, fermée, sans timbre. Sur l'enveloppe, une écriture penchée, à l'encre bleue : <i>Pour Rosa</i>. Et en dessous, plus petit : <i>Liège, le 3 mars 1948</i>.
1948 ! Cette lettre attendait sous l'escalier depuis presque quatre-vingts ans. Qui était Rosa ? Pourquoi la lettre n'était-elle jamais partie ?
Ilyas est arrivé derrière moi, en pyjama.
— C'est quoi ? a-t-il chuchoté.
— Un secret, ai-je dit. Et tu ne dis rien à personne.
Il a hoché la tête, très sérieux. Cette nuit-là, j'ai posé l'enveloppe sur ma table de nuit. Je ne l'ai pas ouverte : on n'ouvre pas une lettre qui ne vous est pas adressée. Mais j'ai mis longtemps à m'endormir.""")

CH2 = P_("""Au rez-de-chaussée habite Monsieur Pirotte. Il a plus de quatre-vingts ans, une canne, une casquette et un caractère de chien. Le premier jour, quand Ilyas a couru dans le couloir, il a ouvert sa porte et il a grogné :
— On n'est pas dans une plaine de jeux, ici !
Depuis, Ilyas passe devant sa porte sur la pointe des pieds. Moi aussi, d'ailleurs.
Pourtant, le samedi suivant, j'ai frappé chez lui, l'enveloppe à la main. S'il habitait ici depuis toujours, il savait peut-être qui était Rosa.
— Qu'est-ce que tu veux ? a-t-il demandé sans ouvrir complètement la porte.
— Bonjour, Monsieur. J'ai trouvé une lettre sous l'escalier. Elle date de 1948. Est-ce que vous connaissez une certaine Rosa ?
Il a regardé l'enveloppe. Son visage a changé d'un coup. Ses mains se sont mises à trembler.
— Cette écriture… a-t-il murmuré. C'est l'écriture de Jeanne. Ma grande sœur.
Il m'a fait entrer. Son appartement sentait le café et les vieux livres. Sur le buffet, il y avait des photos en noir et blanc. Il en a pris une : deux fillettes en tablier, devant une porte que je connaissais bien, celle de notre maison.
— Voilà Jeanne, à gauche. Et à droite, c'est Rosa Bellini. Sa famille est arrivée d'Italie en 1946. Son père était venu travailler dans les charbonnages. Ils habitaient au troisième étage.
— Au troisième ? Mais… c'est chez nous !
— Eh oui, a-t-il dit avec un petit sourire, le premier que je voyais sur son visage. Rosa ne parlait pas un mot de français quand elle est arrivée. Elle avait onze ans. Jeanne l'a aidée. Elles étaient inséparables. Et puis, en 1948, les Bellini sont partis dans le Hainaut, près de Charleroi. Du jour au lendemain.
— Et Jeanne ? Où est-elle ?
Il a reposé la photo.
— Jeanne nous a quittés il y a sept ans. Elle a parlé de Rosa jusqu'à la fin.""")

CH3 = P_("""<span style="font-family:Poppins" class="xs muted">[Monsieur Pirotte a ouvert l'enveloppe devant Zara. Voici la lettre de sa sœur.]</span>
<span style="display:block;text-align:right;font-style:italic">Liège, le 3 mars 1948</span><i>Chère Rosa,</i>
<i>Tu es partie depuis douze jours et la maison est trop silencieuse. Personne ne chante plus dans l'escalier. Ta maman m'a donné votre nouvelle adresse sur un petit papier, mais je l'ai perdu. Je suis bête, hein ? Alors je t'écris quand même, et je garderai cette lettre jusqu'à ce que je te retrouve.</i>
<i>Il faut que je te dise quelque chose. Tu te souviens du jour où les filles de la classe se sont moquées de toi ? Marguerite disait que tu parlais comme un perroquet et que tu devrais retourner dans ton pays. Tout le monde riait. Toi, tu m'as regardée. Tu attendais que je dise quelque chose. Et moi, je n'ai rien dit. J'avais peur qu'elles se moquent de moi aussi. Le soir, tu m'as demandé pourquoi je n'avais pas parlé. Je t'ai répondu que je n'avais rien entendu. C'était un mensonge, Rosa. J'ai tout entendu.</i>
<i>Je pense à ce jour-là tous les soirs. Tu es la meilleure amie que j'aie jamais eue. Tu m'as appris à compter en italien et à faire des pâtes à la main. Moi, je t'ai appris des mots de wallon que la maîtresse ne connaît même pas. Tu vois, nous sommes quittes.</i>
<i>Pardonne-moi. Je te promets qu'à partir d'aujourd'hui, je ne me tairai plus jamais quand quelqu'un se moquera d'un autre.</i>
<i>Je t'embrasse très fort,</i><span style="display:block;text-align:right;font-style:italic">Jeanne</span>
<i>P.-S. Mon petit frère Joseph te dit bonjour. Il demande si tu reviendras pour son anniversaire.</i>""")

CH4 = P_("""Le lundi, tout est allé de travers. En classe de français, Madame Hardy m'a demandé de lire un paragraphe à voix haute. J'ai lu lentement, en cherchant les mots. Au troisième rang, Kevin a imité mon accent. Quelques élèves ont ri. J'ai senti mes joues brûler.
J'ai regardé Léa. Léa, c'est ma voisine de banc, la seule qui me prête ses notes et qui m'attend à la sortie. Elle a baissé les yeux et elle n'a rien dit.
À la récréation, je lui ai demandé pourquoi elle ne m'avait pas défendue. Elle m'a répondu qu'elle n'avait pas fait attention. Je savais que ce n'était pas vrai.
Le soir, à la maison, j'étais une bombe prête à exploser. Ilyas a renversé son verre de lait sur mon cahier de géographie.
— Tu fais toujours tout de travers ! ai-je hurlé.
Il s'est mis à pleurer. Maman est sortie de la cuisine, fatiguée par sa journée de formation.
— Zara, qu'est-ce qui se passe ? Ce n'est pas la faute de ton frère.
— Personne ne me comprend ! Je veux rentrer chez nous !
J'ai claqué la porte de ma chambre et je me suis jetée sur mon lit. Et là, sur ma table de nuit, j'ai vu la boîte en fer. J'ai relu la copie de la lettre que Monsieur Pirotte m'avait donnée : « Tu attendais que je dise quelque chose. Et moi, je n'ai rien dit. »
Soudain, j'ai compris. Rosa, c'était moi aujourd'hui. Et Léa, c'était Jeanne. Elle n'était pas méchante : elle avait peur.
Plus tard, j'ai frappé à la porte d'Ilyas. Il dormait déjà, son vieux lapin en peluche serré contre lui. J'ai posé un dessin sur son oreiller : un château avec une septième marche magique. En dessous, j'ai écrit : <i>Pardon</i>.""")

CH5 = P_("""Il nous a fallu trois semaines pour retrouver Rosa. Monsieur Pirotte a téléphoné à toutes les communes autour de Charleroi. Moi, j'ai écrit à une association d'anciens mineurs italiens. Un mardi soir, une dame nous a rappelés : Rosa Bellini vivait dans une maison de repos à Seraing, à quelques kilomètres de chez nous. Elle avait quatre-vingt-onze ans.
Le dimanche suivant, nous avons pris le bus : Monsieur Pirotte avec sa canne, Ilyas avec un bouquet de tulipes, et moi avec la boîte en fer.
Rosa nous attendait près de la fenêtre. Elle était toute petite, avec des cheveux blancs et des yeux très noirs, très vifs. Monsieur Pirotte s'est approché lentement.
— Rosa ? C'est Joseph. Le petit frère de Jeanne.
Elle l'a regardé longtemps. Puis elle a souri.
— Joseph ! Le petit qui mangeait toutes mes pâtes !
Ils ont ri tous les deux, et j'ai vu que Monsieur Pirotte avait les yeux mouillés. Il a expliqué que Jeanne était morte et qu'elle avait gardé une lettre pour elle pendant toute sa vie. Puis il m'a fait un signe. Je me suis approchée et j'ai demandé à Rosa si elle voulait que je la lise. Elle a répondu que ses yeux étaient fatigués et qu'elle préférait écouter.
Alors j'ai lu. Ma voix tremblait un peu, mon accent aussi, mais cette fois, ça m'était égal. Quand j'ai eu fini, Rosa est restée silencieuse. Puis elle a pris ma main.
— Elle n'avait pas besoin de me demander pardon, a-t-elle dit doucement. Je lui avais pardonné le lendemain. Mais je suis contente de savoir qu'elle y pensait. J'ai attendu cette lettre soixante-dix-huit ans.
Elle m'a demandé d'où je venais et depuis combien de temps j'étais en Belgique. Je lui ai répondu.
— Trois mois, a-t-elle répété. Moi aussi, au début, je voulais rentrer chez moi. Tu verras : un jour, cette ville sera aussi la tienne.""")

CH6 = P_("""Le lendemain, Léa m'attendait devant la grille de l'école. Elle tenait son sac à deux mains, comme un bouclier.
— Zara, je peux te parler ?
J'ai haussé les épaules. Je n'étais plus en colère, mais je voulais savoir ce qu'elle allait dire.
— Lundi, j'ai menti, a-t-elle commencé. J'avais tout entendu. Kevin est méchant, et moi, j'ai eu peur qu'il se moque de moi aussi. C'est nul. Je suis désolée.
Je l'ai regardée. Ses yeux étaient rouges : elle n'avait sans doute pas beaucoup dormi. J'ai pensé à Jeanne, qui avait attendu toute sa vie pour dire la même chose. Léa, elle, avait attendu une seule journée.
— Tu sais, lui ai-je dit, hier, j'ai rencontré une dame de quatre-vingt-onze ans. Elle m'a raconté une histoire qui ressemble beaucoup à la nôtre.
— Raconte !
Pendant tout le chemin jusqu'à la classe, je lui ai tout raconté : la septième marche, la boîte en fer, Monsieur Pirotte, la lettre de Jeanne, le sourire de Rosa. Léa m'écoutait sans m'interrompre, la bouche ouverte.
En français, Madame Hardy a demandé un volontaire pour lire. Kevin a ricané en me regardant. Alors Léa a levé la main, très haut.
— Madame, Zara lit très bien. Et si quelqu'un se moque encore de son accent, c'est à moi qu'il aura affaire.
Il y a eu un grand silence. Puis Madame Hardy m'a tendu le livre. J'ai lu. Personne n'a ri.
Le soir, j'ai remis la boîte en fer sous la septième marche. Vide, cette fois. Ou presque : j'y ai glissé un petit papier. <i>Pour la prochaine fille qui arrivera dans cette maison. Courage. Tu n'es pas seule. Zara.</i>""")


def couverture(w=58):
    """Couverture du roman (illustration originale)."""
    steps = "".join(f'<rect x="{30 + i * 14}" y="{230 - i * 18}" width="{150 - i * 14}" height="18" fill="{"#C98B4E" if i != 6 else "#E0A85E"}" stroke="#7a4f27" stroke-width="1.2"/>' for i in range(9))
    return f'''<svg viewBox="0 0 200 300" width="{w}mm" style="border-radius:1.5mm;box-shadow:0 1.5mm 4mm rgba(0,0,0,.25)" font-family="Poppins">
<rect width="200" height="300" fill="#1F2A44"/><rect x="0" y="0" width="200" height="300" fill="url(#lg)"/>
<defs><radialGradient id="lg" cx="0.62" cy="0.52" r="0.5"><stop offset="0" stop-color="#FFD166" stop-opacity=".55"/><stop offset="1" stop-color="#1F2A44" stop-opacity="0"/></radialGradient></defs>
{steps}<rect x="104" y="112" width="40" height="8" fill="#5a3a1c"/>
<rect x="108" y="96" width="30" height="16" fill="#9aa1b1" stroke="#555"/><rect x="105" y="90" width="36" height="7" fill="#b9bfcc" stroke="#555" transform="rotate(-18 105 97)"/>
<rect x="114" y="80" width="22" height="15" fill="#F4E9D8" stroke="#a08a63" transform="rotate(-8 125 88)"/><path d="M114 81 L125 89 L136 79" fill="none" stroke="#a08a63" transform="rotate(-8 125 88)"/>
<text x="100" y="32" font-size="9" fill="#FFD166" text-anchor="middle" letter-spacing="2">HÉLÈNE MARCHAL</text>
<text x="100" y="56" font-size="19" font-weight="800" fill="#fff" text-anchor="middle">La Lettre</text><text x="100" y="77" font-size="19" font-weight="800" fill="#fff" text-anchor="middle">sous l'escalier</text>
<rect x="0" y="270" width="200" height="30" fill="{MC}"/><text x="100" y="289" font-size="8" fill="#fff" text-anchor="middle">Éditions de la Passerelle · Grand Angle</text></svg>'''


def quatrieme():
    return f'''<div class="card" style="{SERIF};background:#1F2A44;color:#fff;font-size:9.8pt;padding:4mm 5mm">
<p style="margin:0 0 1.5mm 0">Zara a quatorze ans. Depuis trois mois, elle vit à Liège avec sa mère et son petit frère, dans une vieille maison dont l'escalier grince. Un soir de colère, une marche se soulève… et Zara découvre une lettre jamais envoyée, datée de 1948.</p>
<p style="margin:0 0 1.5mm 0">Qui était Rosa ? Pourquoi Jeanne n'a-t-elle jamais posté sa lettre ? Avec l'aide de Monsieur Pirotte, le voisin le plus grognon de la rue, Zara se lance dans une enquête qui va la mener bien plus loin qu'elle ne l'imaginait…</p>
<p style="margin:0 0 2mm 0"><b>Un roman lumineux sur l'amitié, l'exil et le courage de parler.</b></p>
<div class="flex xs" style="justify-content:space-between;font-family:Poppins;opacity:.85"><span>Dès 12 ans · 168 pages</span><span>Collection Grand Angle</span><span style="background:#fff;color:#1F2A44;padding:.5mm 2mm;letter-spacing:1px">||||| ||| ||||</span></div></div>'''


